  skip?: (c: Context) => boolean
  /**
   * Custom response handler when the rate limit is exceeded.
   * Defaults to a 429 JSON response.
   */
  handler?: (c: Context) => Response | Promise<Response>
}

interface RateLimitEntry {
  count: number
  resetAt: number
}

const defaultKeyGenerator = (c: Context): string => {
  const xff = c.req.header('x-forwarded-for')
  if (xff) {
    return xff.split(',')[0].trim()
  }
  return 'global'
}

/**
 * Rate Limit Middleware for Hono.
 *
 * @param {RateLimitOptions} [options] - The options for the rate limit middleware.
 * @param {number} [options.limit=100] - The maximum number of requests per window.
 * @param {number} [options.windowMs=60000] - The time window in milliseconds.
 * @param {Function} [options.keyGenerator] - Generates the key used to identify a client. Defaults to the remote IP.
 * @param {Function} [options.skip] - Predicate to skip rate limiting for certain requests.
 * @param {Function} [options.handler] - Custom 429 response handler.
 * @returns {MiddlewareHandler} The middleware handler function.
 *
 * @example
 * ```ts
 * const app = new Hono()
 *
 * app.use('/api/*', rateLimit({ limit: 10, windowMs: 1000 }))
 *
 * app.get('/api/hello', (c) => c.text('Hello!'))
 * ```
 */
export const rateLimit = (options?: RateLimitOptions): MiddlewareHandler => {
  const limit = options?.limit ?? 100
  const windowMs = options?.windowMs ?? 60000
  const keyGenerator = options?.keyGenerator ?? defaultKeyGenerator
  const skip = options?.skip
  const handler =
    options?.handler ??
    ((c: Context) =>
      new Response(JSON.stringify({ error: 'Too Many Requests' }), {
        status: 429,
        headers: { 'content-type': 'application/json' },
      }))

  const store = new Map<string, RateLimitEntry>()

  return async function rateLimit(c, next) {
    if (skip?.(c)) {
      return next()
    }

    const key = keyGenerator(c)
    const now = Date.now()
    let entry = store.get(key)

    if (!entry || entry.resetAt <= now) {
      entry = { count: 0, resetAt: now + windowMs }
      store.set(key, entry)
    }

    entry.count++

    const remaining = Math.max(0, limit - entry.count)
    c.header('X-RateLimit-Limit', String(limit))
    c.header('X-RateLimit-Remaining', String(remaining))
    c.header('X-RateLimit-Reset', String(Math.ceil(entry.resetAt / 1000)))

    if (entry.count > limit) {
      c.header('Retry-After', String(Math.ceil((entry.resetAt - now) / 1000)))
      return handler(c)
    }

    await next()
  }
}

