import { rateLimit } from '.'

describe('Rate Limit Middleware', () => {
  describe('Defaults', () => {
    let app: Hono

    beforeEach(() => {
      app = new Hono()
      app.use('/api/*', rateLimit({ limit: 3, windowMs: 60000 }))
      app.get('/api/hello', (c) => c.text('hello'))
    })

    it('Should allow requests below the limit', async () => {
      for (let i = 0; i < 3; i++) {
        const req = new Request('http://localhost/api/hello')
        req.headers.set('X-Forwarded-For', '10.0.0.1')
        const res = await app.request(req)
        expect(res.status).toBe(200)
        expect(await res.text()).toBe('hello')
      }
    })

    it('Should expose rate limit headers', async () => {
      const req = new Request('http://localhost/api/hello')
      req.headers.set('X-Forwarded-For', '10.0.0.2')
      const res = await app.request(req)
      expect(res.status).toBe(200)
      expect(res.headers.get('X-RateLimit-Limit')).toBe('3')
      expect(res.headers.get('X-RateLimit-Remaining')).toBe('2')
      expect(res.headers.get('X-RateLimit-Reset')).not.toBeNull()
    })

    it('Should return 429 with JSON body when the limit is exceeded', async () => {
      const ip = '10.0.0.3'
      for (let i = 0; i < 3; i++) {
        const req = new Request('http://localhost/api/hello')
        req.headers.set('X-Forwarded-For', ip)
        const res = await app.request(req)
        expect(res.status).toBe(200)
      }

      const req = new Request('http://localhost/api/hello')
      req.headers.set('X-Forwarded-For', ip)
      const res = await app.request(req)
      expect(res.status).toBe(429)
      expect(res.headers.get('content-type')).toContain('application/json')
      expect(res.headers.get('Retry-After')).not.toBeNull()
      const body = await res.json()
      expect(body).toEqual({ error: 'Too Many Requests' })
    })

    it('Should track different keys independently', async () => {
      for (let i = 0; i < 3; i++) {
        const req = new Request('http://localhost/api/hello')
        req.headers.set('X-Forwarded-For', '10.0.0.4')
        const res = await app.request(req)
        expect(res.status).toBe(200)
      }

      const blockedReq = new Request('http://localhost/api/hello')
      blockedReq.headers.set('X-Forwarded-For', '10.0.0.4')
      const blocked = await app.request(blockedReq)
      expect(blocked.status).toBe(429)

      const otherReq = new Request('http://localhost/api/hello')
      otherReq.headers.set('X-Forwarded-For', '10.0.0.5')
      const other = await app.request(otherReq)
      expect(other.status).toBe(200)
    })

    it('Should reset after the window expires', async () => {
      vi.useFakeTimers()
      try {
        const start = new Date('2026-01-01T00:00:00Z')
        vi.setSystemTime(start)

        const limitedApp = new Hono()
        limitedApp.use('/api/*', rateLimit({ limit: 2, windowMs: 1000 }))
        limitedApp.get('/api/hello', (c) => c.text('hello'))

        for (let i = 0; i < 2; i++) {
          const req = new Request('http://localhost/api/hello')
          req.headers.set('X-Forwarded-For', '10.0.0.6')
          const res = await limitedApp.request(req)
          expect(res.status).toBe(200)
        }

        const blockedReq = new Request('http://localhost/api/hello')
        blockedReq.headers.set('X-Forwarded-For', '10.0.0.6')
        const blocked = await limitedApp.request(blockedReq)
        expect(blocked.status).toBe(429)

        vi.setSystemTime(new Date(start.getTime() + 1500))

        const recoveredReq = new Request('http://localhost/api/hello')
        recoveredReq.headers.set('X-Forwarded-For', '10.0.0.6')
        const recovered = await limitedApp.request(recoveredReq)
        expect(recovered.status).toBe(200)
      } finally {
        vi.useRealTimers()
      }
    })
  })

  describe('Custom key generator', () => {
    it('Should use the custom keyGenerator', async () => {
      const app = new Hono()
      app.use(
        '/api/*',
        rateLimit({
          limit: 1,
          windowMs: 60000,
          keyGenerator: (c) => c.req.header('X-User-Id') ?? 'anonymous',
        })
      )
      app.get('/api/hello', (c) => c.text('hello'))

      const firstReq = new Request('http://localhost/api/hello')
      firstReq.headers.set('X-User-Id', 'user-a')
      const first = await app.request(firstReq)
      expect(first.status).toBe(200)

      const blockedReq = new Request('http://localhost/api/hello')
      blockedReq.headers.set('X-User-Id', 'user-a')
      const blocked = await app.request(blockedReq)
      expect(blocked.status).toBe(429)

      const otherReq = new Request('http://localhost/api/hello')
      otherReq.headers.set('X-User-Id', 'user-b')
      const other = await app.request(otherReq)
      expect(other.status).toBe(200)
    })
  })

