      app.use(
        '/api/*',
        rateLimit({
          limit: 1,
          windowMs: 60000,
          skip: (c) => c.req.header('X-Skip') === 'true',
        })
      )
      app.get('/api/hello', (c) => c.text('hello'))

      for (let i = 0; i < 5; i++) {
        const req = new Request('http://localhost/api/hello')
        req.headers.set('X-Forwarded-For', '10.0.0.7')
        req.headers.set('X-Skip', 'true')
        const res = await app.request(req)
        expect(res.status).toBe(200)
      }
    })

    it('Should still rate limit when skip returns false', async () => {
      const app = new Hono()
      app.use(
        '/api/*',
        rateLimit({
          limit: 1,
          windowMs: 60000,
          skip: () => false,
        })
      )
