      firstReq.headers.set('X-Forwarded-For', '10.0.0.8')
      const first = await app.request(firstReq)
      expect(first.status).toBe(200)

      const blockedReq = new Request('http://localhost/api/hello')
      blockedReq.headers.set('X-Forwarded-For', '10.0.0.8')
      const blocked = await app.request(blockedReq)
      expect(blocked.status).toBe(429)
    })
  })

  describe('Custom handler', () => {
    it('Should use the custom handler when the limit is exceeded', async () => {
      const app = new Hono()
      app.use(
        '/api/*',
        rateLimit({
          limit: 1,
          windowMs: 60000,
          handler: (c) => c.text('slow down', 429),
        })
      )
      app.get('/api/hello', (c) => c.text('hello'))

      const firstReq = new Request('http://localhost/api/hello')
      firstReq.headers.set('X-Forwarded-For', '10.0.0.9')
      const first = await app.request(firstReq)
      expect(first.status).toBe(200)

      const blockedReq = new Request('http://localhost/api/hello')
      blockedReq.headers.set('X-Forwarded-For', '10.0.0.9')
      const blocked = await app.request(blockedReq)
      expect(blocked.status).toBe(429)
      expect(await blocked.text()).toBe('slow down')
    })

    it('Should support async handlers', async () => {
      const app = new Hono()
      app.use(
        '/api/*',
        rateLimit({
          limit: 1,
          windowMs: 60000,
          handler: async (c) =>
            new Response(JSON.stringify({ retry: true }), {
              status: 429,
              headers: { 'content-type': 'application/json' },
            }),
        })
      )
      app.get('/api/hello', (c) => c.text('hello'))

      const firstReq = new Request('http://localhost/api/hello')
      firstReq.headers.set('X-Forwarded-For', '10.0.0.10')
      await app.request(firstReq)

      const blockedReq = new Request('http://localhost/api/hello')
      blockedReq.headers.set('X-Forwarded-For', '10.0.0.10')
      const blocked = await app.request(blockedReq)
      expect(blocked.status).toBe(429)
      expect(await blocked.json()).toEqual({ retry: true })
    })
  })
})

